INSERT INTO bare_act_sections (act_id, chapter_number, chapter_title, section_number, section_title, section_text, sequence_order) VALUES
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER I', 'PRELIMINARY', '1', 'Short title, local extent, saving of usages relating to hundis, etc., commencement.', 'This Act may be called the Negotiable Instruments Act, 1881. It extends to the whole of India  but nothing herein contained affects the Indian Paper Currency Act, 1871, Section 21, or affects any local usage relating to any instrument in an oriental language: Provided that such usages may be excluded by any words in the body of the instrument which indicate an intention that the legal relations of the parties thereto shall be governed by this Act; and it shall come into force on the first day of March, 1882.', 0),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER I', 'PRELIMINARY', '2', 'Repeal of enactments.', '[Repealed by the Repealing and Amending Act, 1891 (12 of 1891), Section 2 and Schedule I.]', 1),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER I', 'PRELIMINARY', '3', 'Interpretation clause.', 'In this Act— "Banker" includes any person acting as a banker and any post office savings bank.', 2),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '4', '“Promissory note.”', 'A “promissory note” is an instrument in writing (not being a bank-note or a currency-note) containing an unconditional undertaking, signed by the maker, to pay a certain sum of money only to, or to the order of, a certain person, or to the bearer of the instrument.', 3),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '5', '“Bill of exchange.”', 'A “bill of exchange” is an instrument in writing containing an unconditional order, signed by the maker, directing a certain person to pay a certain sum of money only to, or to the order of, a certain person or to the bearer of the instrument.', 4),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '6', '“Cheque.”', 'A “cheque” is a bill of exchange drawn on a specified banker and not expressed to be payable otherwise than on demand and it includes the electronic image of a truncated cheque and a cheque in the electronic form. Explanation I.—For the purposes of this section, the expressions— (a) “a cheque in the electronic form” means a cheque drawn in electronic form by using any computer resource and signed in a secure system with digital signature (with or without biometrics signature) and asymmetric crypto system or with electronic signature, as the case may be; (b) “a truncated cheque” means a cheque which is truncated during the course of a clearing cycle, either by the clearing house or by the bank whether paying or receiving payment, immediately on generation of an electronic image for transmission, substituting the further physical movement of the cheque in writing. Explanation II.—For the purposes of this section, the expression “clearing house” means the clearing house managed by the Reserve Bank of India or a clearing house recognised as such by the Reserve Bank of India. Explanation III.—For the purposes of this section, the expressions “asymmetric crypto system”, “computer resource”, “digital signature”, “electronic form” and “electronic signature” shall have the same meanings respectively assigned to them in the Information Technology Act, 2000.', 5),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '7', '“Drawer”, “Drawee”. “Drawee in case of need”. “Acceptor”. “Acceptor for honour”. “Payee”.', 'The maker of a bill of exchange or cheque is called the “drawer”; the person thereby directed to pay is called the “drawee”. When in the bill or in any indorsement thereon the name of any person is given in addition to the drawee to be resorted to in case of need, such person is called a “drawee in case of need”. After the drawee has signed his assent upon the bill, or, if there are more parts thereof than one, upon one of such parts, and delivered the same, or given notice of such signing to the holder or to some person on his behalf, he is called the “acceptor”. When a bill of exchange has been noted or protested for non-acceptance or for better security and another person accepts it supra protest for honour of the drawer or of any one of the indorsers, such person is called an “acceptor for honour”. The person named in the instrument, to whom or to whose order the money is by the instrument directed to be paid, is called the “payee”.', 6),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '8', '“Holder”.', 'The “holder” of a promissory note, bill of exchange or cheque means any person entitled in his own name to the possession thereof and to receive or recover the amount due thereon from the parties thereto. Where the note, bill or cheque is lost or destroyed, its holder is the person so entitled at the time of such loss or destruction.', 7),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '9', '“Holder in due course”.', '“Holder in due course” means any person who for consideration became the possessor of a promissory note, bill of exchange or cheque if payable to bearer, or the payee or indorsee thereof, if payable to order, before the amount mentioned in it became payable and without having sufficient cause to believe that any defect existed in the title of the person from whom he derived his title.', 8),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '10', '“Payment in due course”.', '“Payment in due course” means payment in accordance with the apparent tenor of the instrument in good faith and without negligence to any person in possession thereof under circumstances which do not afford a reasonable ground for believing that he is not entitled to receive payment of the amount therein mentioned.', 9),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '11', 'Inland instrument.', 'A promissory note, bill of exchange or cheque drawn or made in India and made payable in, or drawn upon any person resident in, India shall be deemed to be an inland instrument.', 10),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '12', 'Foreign instrument.', 'Any such instrument not so drawn, made or made payable shall be deemed to be a foreign instrument.', 11),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '13', '“Negotiable instrument”.', '(1) A “negotiable instrument” means a promissory note, bill of exchange or cheque payable either to order or to bearer. Explanation (i)—A promissory note, bill of exchange or cheque is payable to order which is expressed to be so payable or which is expressed to be payable to a particular person, and does not contain words prohibiting transfer or indicating an intention that it shall not be transferable. Explanation (ii)—A promissory note, bill of exchange or cheque is payable to bearer which is expressed to be so payable or on which the only or last indorsement is an indorsement in blank. Explanation (iii)—Where a promissory note, bill of exchange or cheque, either originally or by indorsement, is expressed to be payable to the order of a specified person, and not to him or his order, it is nevertheless payable to him or his order at his option. (2) A negotiable instrument may be made payable to two or more payees jointly, or it may be made payable in the alternative to one of two, or one or some of several payees.', 12),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '14', 'Negotiation.', 'When a promissory note, bill of exchange or cheque is transferred to any person, so as to constitute that person the holder thereof, the instrument is said to be negotiated.', 13),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '15', 'Indorsement.', 'When the maker or holder of a negotiable instrument signs the same, otherwise than as such maker, for the purpose of negotiation, on the back or face thereof or on a slip of paper annexed thereto, or so signs for the same purpose a stamped paper intended to be completed as a negotiable instrument, he is said to indorse the same, and is called the “indorser”.', 14),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '16', 'Indorsement “in blank” and “in full”. “Indorsee”.', '(1) If the indorser signs his name only, the indorsement is said to be “in blank,” and if he adds a direction to pay the amount mentioned in the instrument to, or to the order of, a specified person, the indorsement is said to be “in full”, and the person so specified is called the “indorsee” of the instrument. (2) The provisions of this Act relating to a payee shall apply with the necessary modifications to an indorsee.', 15),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '17', 'Ambiguous instruments.', 'Where an instrument may be construed either as a promissory note or bill of exchange, the holder may at his election treat it as either, and the instrument shall be thenceforward treated accordingly.', 16),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '18', 'Where amount is stated differently in figures and words.', 'If the amount undertaken or ordered to be paid is stated differently in figures and in words, the amount stated in words shall be the amount undertaken or ordered to be paid.', 17),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '19', 'Instruments payable on demand.', 'A promissory note or bill of exchange, in which no time for payment is specified, and a cheque, are payable on demand.', 18),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '20', 'Inchoate stamped instruments.', 'Where one person signs and delivers to another a paper stamped in accordance with the law relating to negotiable instruments then in force in India, and either wholly blank or having written thereon an incomplete negotiable instrument, he thereby gives prima facie authority to the holder thereof to make or complete, as the case may be, upon it a negotiable instrument, for any amount specified therein and not exceeding the amount covered by the stamp. The person so signing shall be liable upon such instrument, in the capacity in which he signed the same, to any holder in due course for such amount.', 19),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '21', '“At sight” — “On presentment” — “After sight”.', 'In a promissory note or bill of exchange the expressions “at sight” and “on presentment” mean on demand. The expression “after sight” means, in a promissory note, after presentment for sight, and, in a bill of exchange, after acceptance, or noting for non-acceptance, or protest for non-acceptance.', 20),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '22', '“Maturity”. Days of grace.', 'The maturity of a promissory note or bill of exchange is the date at which it falls due. Every promissory note or bill of exchange which is not expressed to be payable on demand, at sight or on presentment is at maturity on the third day after the day on which it is expressed to be payable.', 21),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '23', 'Calculating maturity of bill or note payable so many months after date or sight.', 'In calculating the date at which a promissory note or bill of exchange, made payable a stated number of months after date or after sight, or after a certain event, is at maturity, the period stated shall be held to terminate on the day of the month which corresponds with the day on which the instrument is dated, or presented for acceptance or sight, or noted for non-acceptance, or protested for non-acceptance, or the event happens... (full calculation rules as per Act).', 22),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '24', 'Calculating maturity of bill or note payable so many days after date or sight.', 'In calculating the date at which a promissory note or bill of exchange made payable a certain number of days after date or after sight or after a certain event is at maturity, the day of the date, or of presentment for acceptance or sight, or of protest for non-acceptance, or on which the event happens, shall be excluded.', 23),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER II', 'OF NOTES, BILLS AND CHEQUES', '25', 'When day of maturity is a holiday.', 'When the day on which a promissory note or bill of exchange is at maturity is a public holiday, the instrument shall be deemed to be due on the next preceding business day. Explanation.—The expression “public holiday” includes Sundays and any other day declared by the Central Government, by notification in the Official Gazette, to be a public holiday.', 24),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '26', 'Capacity to make, etc., promissory notes, etc. Minor.', 'Every person capable of contracting, according to the law to which he is subject, may bind himself and be bound by the making, drawing, acceptance, indorsement, delivery and negotiation of a promissory note, bill of exchange or cheque. A minor may draw, indorse, deliver and negotiate such instrument so as to bind all parties except himself.', 25),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '27', 'Agency.', 'Every person capable of binding himself or of being bound may so bind himself or be bound by a duly authorized agent acting in his name.', 26),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '28', 'Liability of agent signing.', 'An agent who signs his name to a promissory note, bill of exchange or cheque without indicating thereon that he signs as agent, or that he does not intend thereby to incur personal responsibility, is liable personally on the instrument, except to those who induced him to sign upon the belief that the principal only would be held liable.', 27),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '29', 'Liability of legal representative signing.', 'A legal representative of a deceased person who signs his name to a promissory note, bill of exchange or cheque is liable personally thereon unless he expressly limits his liability to the extent of the assets received by him as such.', 28),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '30', 'Liability of drawer.', 'The drawer of a bill of exchange or cheque is bound, in case of dishonour by the drawee or acceptor thereof, to compensate the holder, provided due notice of dishonour has been given to, or received by, the drawer.', 29),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '31', 'Liability of drawee of cheque.', 'The drawee of a cheque having sufficient funds of the drawer in his hands properly applicable to the payment of such cheque must pay the cheque when duly required so to do, and, in default of such payment, must compensate the drawer for any loss or damage caused by such default.', 30),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '32', 'Liability of maker of note and acceptor of bill.', 'In the absence of a contract to the contrary, the maker of a promissory note and the acceptor before maturity of a bill of exchange are bound to pay the amount thereof at maturity according to the apparent tenor of the note or acceptance respectively...', 31),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '33', 'Only drawee can be acceptor except in need or for honour.', 'No person except the drawee of a bill of exchange, or all or some of several drawees, or a person named therein as a drawee in case of need, or an acceptor for honour, can bind himself by an acceptance.', 32),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '34', 'Acceptance by several drawees not partners.', 'Where there are several drawees of a bill of exchange who are not partners, each of them can accept it for himself, but none of them can accept it for another without his authority.', 33),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '35', 'Liability of indorser.', 'In the absence of a contract to the contrary, whoever indorses and delivers a negotiable instrument before maturity is bound thereby to every subsequent holder, in case of dishonour...', 34),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '36', 'Liability of prior parties to holder in due course.', 'Every prior party to a negotiable instrument is liable thereon to a holder in due course until the instrument is duly satisfied.', 35),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '37', 'Maker, drawer and acceptor principals.', 'The maker of a promissory note or cheque, the drawer of a bill of exchange until acceptance, and the acceptor are, in the absence of a contract to the contrary, respectively liable thereon as principal debtors...', 36),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '38', 'Prior party a principal in respect of each subsequent party.', 'As between the parties so liable as sureties, each prior party is, in the absence of a contract to the contrary, also liable thereon as a principal debtor in respect of each subsequent party.', 37),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '39', 'Suretyship.', 'When the holder of an accepted bill of exchange enters into any contract with the acceptor which would discharge the other parties, the holder may expressly reserve his right to charge the other parties...', 38),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '40', 'Discharge of indorser’s liability.', 'Where the holder of a negotiable instrument, without the consent of the indorser, destroys or impairs the indorser’s remedy against a prior party, the indorser is discharged from liability to the holder to the same extent...', 39),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '41', 'Acceptor bound, although indorsement forged.', 'An acceptor of a bill of exchange already indorsed is not relieved from liability by reason that such indorsement is forged, if he knew or had reason to believe the indorsement to be forged when he accepted the bill.', 40),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '42', 'Acceptance of bill drawn in fictitious name.', 'An acceptor of a bill of exchange drawn in a fictitious name and payable to the drawer''s order is not relieved from liability to any holder in due course claiming under an indorsement by the same hand as the drawer''s signature...', 41),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '43', 'Negotiable instrument made, etc., without consideration.', 'A negotiable instrument made, drawn, accepted, indorsed or transferred without consideration, or for a consideration which fails, creates no obligation of payment between the parties...', 42),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '44', 'Partial absence or failure of money-consideration.', 'When the consideration for which a person signed a promissory note, bill of exchange or cheque consisted of money, and was originally absent in part or has subsequently failed in part, the sum which a holder standing in immediate relation with such signer is entitled to receive from him is proportionally reduced.', 43),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '45', 'Partial failure of consideration not consisting of money.', 'Where a part of the consideration for which a person signed a promissory note, bill of exchange or cheque, though not consisting of money, is ascertainable in money without collateral enquiry, and there has been a failure of that part, the sum which a holder standing in immediate relation with such signer is entitled to receive from him is proportionally reduced.', 44),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER III', 'PARTIES TO NOTES, BILLS AND CHEQUES', '45A', 'Holder’s right to duplicate of lost bill.', 'Where a bill of exchange has been lost before it is over-due, the person who was the holder of it may apply to the drawer to give him another bill of the same tenor, giving security to the drawer, if required, to indemnify him against all persons whatever in case the bill alleged to have been lost shall be found again.', 45),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '46', 'Delivery.', 'The making, acceptance or indorsement of a promissory note, bill of exchange or cheque is completed by delivery, actual or constructive.', 46),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '47', 'Negotiation by delivery.', 'Subject to the provisions of section 58, a promissory note, bill of exchange or cheque payable to bearer is negotiable by delivery thereof.', 47),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '48', 'Negotiation by indorsement.', 'Subject to the provisions of section 58, a promissory note, bill of exchange or cheque payable to order is negotiable by the holder by indorsement and delivery thereof.', 48),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '49', 'Conversion of indorsement in blank into indorsement in full.', 'The holder of a negotiable instrument indorsed in blank may convert the indorsement in blank into an indorsement in full.', 49),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '50', 'Effect of indorsement.', 'The indorsement of a negotiable instrument followed by delivery transfers to the indorsee the property therein with the right of further negotiation.', 50),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '51', 'Who may negotiate.', 'Every sole maker, drawer, payee or indorsee, or all of several joint makers, drawers, payees or indorsees, of a negotiable instrument may indorse and negotiate the same.', 51),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '52', 'Indorser who excludes his own liability or makes it conditional.', 'The indorser of a negotiable instrument may, by express words in the indorsement, exclude his own liability thereon, or make such liability depend upon the happening of a specified event.', 52),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '53', 'Holder deriving title from holder in due course.', 'A holder of a negotiable instrument who derives title from a holder in due course has the rights thereon of that holder in due course.', 53),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '54', 'Instrument indorsed in blank.', 'Subject to the provisions as to crossed cheques, a negotiable instrument indorsed in blank is payable to the bearer thereof.', 54),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '55', 'Conversion of indorsement in blank into indorsement in full.', 'If a negotiable instrument, after having been indorsed in blank, is indorsed in full, the amount of it cannot be claimed from the indorser in full, except by the person to whom it has been indorsed in full...', 55),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '56', 'Indorsement for part of sum due.', 'No writing on a negotiable instrument is valid for the purpose of negotiation if such writing purports to transfer only a part of the amount appearing to be due on the instrument.', 56),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '57', 'Legal representative cannot by delivery only negotiate instrument indorsed by deceased.', 'The legal representative of a deceased person cannot negotiate by delivery only a promissory note, bill of exchange or cheque payable to order and indorsed by the deceased but not delivered.', 57),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '58', 'Instrument obtained by unlawful means or for unlawful consideration.', 'When a negotiable instrument has been lost, or has been obtained by means of an offence or fraud, or for an unlawful consideration, no possessor or indorsee who claims through the person who found or so obtained the instrument is entitled to receive the amount due thereon...', 58),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '59', 'Instrument acquired after dishonour or when overdue. Accommodation note or bill.', 'The holder of a negotiable instrument, who has acquired it after dishonour, with notice thereof, or after maturity, has only, as against the other parties, the rights thereon of his transferor.', 59),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IV', 'OF NEGOTIATION', '60', 'Instrument negotiable till payment or satisfaction.', 'A negotiable instrument may be negotiated (except by the maker, drawee or acceptor after maturity) until payment or satisfaction thereof by the maker, drawee or acceptor at or after maturity, but not after such payment or satisfaction.', 60),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '61', 'Presentment for acceptance.', 'A bill of exchange payable after sight must, if no time or place is specified therein for presentment, be presented to the drawee thereof for acceptance...', 61),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '62', 'Presentment of promissory note for sight.', 'A promissory note, payable at a certain period after sight, must be presented to the maker thereof for sight...', 62),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '63', 'Drawee’s time for deliberation.', 'The holder must, if so required by the drawee of a bill of exchange presented to him for acceptance, allow the drawee forty-eight hours (exclusive of public holidays) to consider whether he will accept it.', 63),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '64', 'Presentment for payment.', '(1) Promissory notes, bills of exchange and cheques must be presented for payment to the maker, acceptor or drawee thereof respectively... (2) Notwithstanding anything contained in section 6, where an electronic image of a truncated cheque is presented for payment...', 64),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '65', 'Hours for presentment.', 'Presentment for payment must be made during the usual hours of business and, if at a banker''s within banking hours.', 65),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '66', 'Presentment for payment of instrument payable after date or sight.', 'A promissory note or bill of exchange, made payable at a specified period after date or sight thereof, must be presented for payment at maturity.', 66),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '67', 'Presentment for payment of promissory note payable by instalments.', 'A promissory note payable by instalments must be presented for payment on the third day after the date fixed for payment of each instalment...', 67),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '68', 'Presentment for payment of instrument payable at specified place and not elsewhere.', 'A promissory note, bill of exchange or cheque made, drawn or accepted payable at a specified place and not elsewhere must... be presented for payment at that place.', 68),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '69', 'Instrument payable at specified place.', 'A promissory note or bill of exchange made, drawn or accepted payable at a specified place must... be presented for payment at that place.', 69),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '70', 'Presentment where no exclusive place specified.', 'A promissory note or bill of exchange, not made payable as mentioned in sections 68 and 69, must be presented for payment at the place of business (if any), or at the usual residence, of the maker, drawee or acceptor thereof...', 70),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '71', 'Presentment when maker, etc., has no known place of business or residence.', 'If the maker, drawee or acceptor... has no known place of business or fixed residence... such presentment may be made to him in person wherever he can be found.', 71),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '72', 'Presentment of cheque to charge drawer.', 'Subject to the provisions of section 84, a cheque must... be presented at the bank upon which it is drawn before the relation between the drawer and his banker has been altered to the prejudice of the drawer.', 72),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '73', 'Presentment of cheque to charge any other person.', 'A cheque must, in order to charge any person except the drawer, be presented within a reasonable time after delivery thereof by such person.', 73),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '74', 'Presentment of instrument payable on demand.', 'Subject to the provisions of section 31, a negotiable instrument payable on demand must be presented for payment within a reasonable time after it is received by the holder.', 74),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '75', 'Presentment by or to agent, representative of deceased, or assignee of insolvent.', 'Presentment for acceptance or payment may be made to the duly authorized agent of the drawee, maker or acceptor... or, where the drawee, maker or acceptor has died, to his legal representative...', 75),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '75A', 'Excuse for delay in presentment for acceptance or payment.', 'Delay in presentment for acceptance or payment is excused if the delay is caused by circumstances beyond the control of the holder...', 76),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '76', 'When presentment unnecessary.', 'No presentment for payment is necessary... in any of the following cases: (a) if the maker, drawee or acceptor intentionally prevents the presentment... (b) as against any party... if he has engaged to pay notwithstanding non-presentment...', 77),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER V', 'OF PRESENTMENT', '77', 'Liability of banker for negligently dealing with bill presented for payment.', 'When a bill of exchange, accepted payable at a specified bank, has been duly presented there for payment and dishonoured, if the banker so negligently or improperly keeps, deals with or delivers back such bill as to cause loss to the holder, he must compensate the holder for such loss.', 78),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VI', 'OF PAYMENT AND INTEREST', '78', 'To whom payment should be made.', 'Subject to the provisions of section 82, clause (c), payment of the amount due on a promissory note, bill of exchange or cheque must... be made to the holder of the instrument.', 79),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VI', 'OF PAYMENT AND INTEREST', '79', 'Interest when rate specified.', 'When interest at a specified rate is expressly made payable on a promissory note or bill of exchange, interest shall be calculated at the rate specified...', 80),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VI', 'OF PAYMENT AND INTEREST', '80', 'Interest when no rate specified.', 'When no rate of interest is specified in the instrument, interest on the amount due thereon shall... be calculated at the rate of eighteen per centum per annum...', 81),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VI', 'OF PAYMENT AND INTEREST', '81', 'Delivery of instrument on payment or indemnity in case of loss.', '(1) Any person liable to pay... is before payment entitled to have it shown, and is on payment entitled to have it delivered up... (2) Where the cheque is an electronic image of a truncated cheque... (3) A certificate issued on the foot of the printout... shall be prima facie proof of such payment.', 82),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '82', 'Discharge from liability.', 'The maker, acceptor or indorser respectively... is discharged from liability thereon— (a) by cancellation; (b) by release; (c) by payment.', 83),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '83', 'Discharge by allowing drawee more than forty-eight hours to accept.', 'If the holder of a bill of exchange allows the drawee more than forty-eight hours... to consider whether he will accept the same, all previous parties not consenting... are thereby discharged...', 84),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '84', 'When cheque not duly presented and drawer damaged thereby.', '(1) Where a cheque is not presented for payment within a reasonable time... and the drawer... suffers actual damage through the delay, he is discharged to the extent of such damage...', 85),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '85', 'Cheque payable to order.', '(1) Where a cheque payable to order purports to be endorsed by or on behalf of the payee, the drawee is discharged by payment in due course. (2) Where a cheque is originally expressed to be payable to bearer, the drawee is discharged by payment in due course to the bearer thereof...', 86),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '85A', 'Drafts drawn by one branch of a bank on another payable to order.', 'Where any draft... drawn by one office of a bank upon another office... purports to be endorsed by or on behalf of the payee, the bank is discharged by payment in due course.', 87),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '86', 'Parties not consenting discharged by qualified or limited acceptance.', 'If the holder of a bill of exchange acquiesces in a qualified acceptance... all previous parties whose consent is not obtained... are discharged...', 88),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '87', 'Effect of material alteration. Alteration by indorsee.', 'Any material alteration of a negotiable instrument renders the same void as against anyone who is a party thereto at the time of making such alteration...', 89),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '88', 'Acceptor or indorser bound notwithstanding previous alteration.', 'An acceptor or indorser of a negotiable instrument is bound by his acceptance or indorsement notwithstanding any previous alteration of the instrument.', 90),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '89', 'Payment of instrument on which alteration is not apparent.', '(1) Where a promissory note, bill of exchange or cheque has been materially altered but does not appear to have been so altered... payment thereof... shall discharge such person or banker... (2) Where the cheque is an electronic image... any difference... shall be a material alteration...', 91),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VII', 'OF DISCHARGE FROM LIABILITY ON NOTES, BILLS AND CHEQUES', '90', 'Extinguishment of rights of action on bill in acceptor’s hands.', 'If a bill of exchange which has been negotiated is, at or after maturity, held by the acceptor in his own right, all rights of action thereon are extinguished.', 92),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '91', 'Dishonour by non-acceptance.', 'A bill of exchange is said to be dishonoured by non-acceptance when the drawee... makes default in acceptance...', 93),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '92', 'Dishonour by non-payment.', 'A promissory note, bill of exchange or cheque is said to be dishonoured by non-payment when the maker... makes default in payment...', 94),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '93', 'By and to whom notice should be given.', 'When a promissory note, bill of exchange or cheque is dishonoured... the holder thereof... must give notice that the instrument has been so dishonoured to all other parties whom the holder seeks to make severally liable thereon...', 95),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '94', 'Mode in which notice may be given.', 'Notice of dishonour may be given to a duly authorized agent... may be oral or written; may, if written, be sent by post...', 96),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '95', 'Party receiving must transmit notice of dishonour.', 'Any party receiving notice of dishonour must... give notice of dishonour to such party within a reasonable time...', 97),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '96', 'Agent for presentment.', 'When the instrument is deposited with an agent for presentment, the agent is entitled to the same time to give notice to his principal...', 98),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '97', 'When party to whom notice given is dead.', 'When the party to whom notice of dishonour is dispatched is dead, but the party dispatching the notice is ignorant of his death, the notice is sufficient.', 99),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER VIII', 'OF NOTICE OF DISHONOUR', '98', 'When notice of dishonour is unnecessary.', 'No notice of dishonour is necessary— (a) when it is dispensed with by the party entitled thereto; (b) in order to charge the drawer, when he has countermanded payment... (g) when the party entitled to notice... promises unconditionally to pay the amount due...', 100),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '99', 'Noting.', 'When a promissory note or bill of exchange has been dishonoured... the holder may cause such dishonour to be noted by a notary public...', 101),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '100', 'Protest. Protest for better security.', 'When a promissory note or bill of exchange has been dishonoured... the holder may... cause such dishonour to be noted and certified by a notary public. Such certificate is called a protest.', 102),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '101', 'Contents of protest.', 'A protest under section 100 must contain— (a) either the instrument itself... (b) the name of the person... (c) a statement that payment... has been demanded...', 103),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '102', 'Notice of protest.', 'When a promissory note or bill of exchange is required by law to be protested, notice of such protest must be given instead of notice of dishonour...', 104),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '103', 'Protest for non-payment after dishonour by non-acceptance.', 'All bills of exchange drawn payable at some other place... may... be protested for non-payment...', 105),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '104', 'Protest of foreign bills.', 'Foreign bills of exchange must be protested for dishonour when such protest is required by the law of the place where they are drawn.', 106),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER IX', 'OF NOTING AND PROTEST', '104A', 'When noting equivalent to protest.', 'For the purposes of this Act, where a bill or note is required to be protested within a specified time... it is sufficient that the bill has been noted for protest before the expiration of the specified time...', 107),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER X', 'OF REASONABLE TIME', '105', 'Reasonable time.', 'In determining what is a reasonable time for presentment... regard shall be had to the nature of the instrument and the usual course of dealing...', 108),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER X', 'OF REASONABLE TIME', '106', 'Reasonable time of giving notice of dishonour.', 'If the holder and the party to whom notice... carry on business or live in different places, such notice is given within a reasonable time if it is dispatched by the next post...', 109),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER X', 'OF REASONABLE TIME', '107', 'Reasonable time for transmitting such notice.', 'A party receiving notice of dishonour... transmits the notice within a reasonable time if he transmits it within the same time after its receipt as he would have had to give notice if he had been the holder.', 110),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '108', 'Acceptance for honour.', 'When a bill of exchange has been noted or protested for non-acceptance or for better security, any person not being a party already liable thereon may... accept the same for the honour of any party thereto.', 111),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '109', 'How acceptance for honour must be made.', 'A person desiring to accept for honour must... declare that he accepts under protest the protested bill for the honour of the drawer or of a particular indorser...', 112),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '110', 'Acceptance not specifying for whose honour it is made.', 'Where the acceptance does not express for whose honour it is made it shall be deemed to be made for the honour of the drawer.', 113),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '111', 'Liability of acceptor for honour.', 'An acceptor for honour binds himself to all parties subsequent to the party for whose honour he accepts to pay the amount of the bill if the drawee do not...', 114),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '112', 'When acceptor for honour may be charged.', 'An acceptor for honour cannot be charged unless the bill has at its maturity been presented to the drawee for payment, and has been dishonoured by him...', 115),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '113', 'Payment for honour.', 'When a bill of exchange has been noted or protested for non-payment, any person may pay the same for the honour of any party liable...', 116),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '114', 'Right of payer for honour.', 'Any person so paying is entitled to all the rights in respect of the bill, of the holder at the time of such payment...', 117),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '115', 'Drawee in case of need.', 'Where a drawee in case of need is named in a bill of exchange... the bill is not dishonoured until it has been dishonoured by such drawee.', 118),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XI', 'OF ACCEPTANCE AND PAYMENT FOR HONOUR AND REFERENCE IN CASE OF NEED', '116', 'Acceptance and payment without protest.', 'A drawee in case of need may accept and pay the bill of exchange without previous protest.', 119),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XII', 'OF COMPENSATION', '117', 'Rules as to compensation.', 'The compensation payable in case of dishonour... shall be determined by the following rules: (a) the holder is entitled to the amount due... together with the expenses... (b) when the person charged resides at a place different... (c) an indorser... is entitled to the amount so paid with interest at eighteen per centum...', 120),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIII', 'SPECIAL RULES OF EVIDENCE', '118', 'Presumptions as to negotiable instruments.', 'Until the contrary is proved, the following presumptions shall be made: (a) of consideration; (b) as to date; (c) as to time of acceptance; (d) as to time of transfer; (e) as to order of indorsements; (f) as to stamp; (g) that holder is a holder in due course.', 121),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIII', 'SPECIAL RULES OF EVIDENCE', '119', 'Presumption on proof of protest.', 'In a suit upon an instrument which has been dishonoured, the Court shall, on proof of the protest, presume the fact of dishonour...', 122),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIII', 'SPECIAL RULES OF EVIDENCE', '120', 'Estoppel against denying original validity of instrument.', 'No maker of a promissory note, and no drawer of a bill of exchange or cheque... shall... be permitted to deny the validity of the instrument as originally made or drawn.', 123),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIII', 'SPECIAL RULES OF EVIDENCE', '121', 'Estoppel against denying capacity of payee to indorse.', 'No maker of a promissory note and no acceptor of a bill of exchange payable to order shall... be permitted to deny the payee''s capacity... to indorse the same.', 124),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIII', 'SPECIAL RULES OF EVIDENCE', '122', 'Estoppel against denying signature or capacity of prior party.', 'No indorser of a negotiable instrument shall... be permitted to deny the signature or capacity to contract of any prior party to the instrument.', 125),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '123', 'Cheque crossed generally.', 'Where a cheque bears across its face an addition of the words “and company”... or of two parallel transverse lines simply... that addition shall be deemed a crossing, and the cheque shall be deemed to be crossed generally.', 126),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '124', 'Cheque crossed specially.', 'Where a cheque bears across its face an addition of the name of a banker... that addition shall be deemed a crossing and the cheque shall be deemed to be crossed specially...', 127),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '125', 'Crossing after issue.', 'Where a cheque is uncrossed, the holder may cross it generally or specially... Where a cheque is crossed generally or specially, the holder may add the words “not negotiable”...', 128),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '126', 'Payment of cheque crossed generally. Payment of cheque crossed specially.', 'Where a cheque is crossed generally, the banker... shall not pay it otherwise than to a banker. Where a cheque is crossed specially, the banker... shall not pay it otherwise than to the banker to whom it is crossed...', 129),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '127', 'Payment of cheque crossed specially more than once.', 'Where a cheque is crossed specially to more than one banker, except when crossed to an agent for collection, the banker... shall refuse payment thereof.', 130),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '128', 'Payment in due course of crossed cheque.', 'Where the banker on whom a crossed cheque is drawn has paid the same in due course, the banker paying the cheque... shall respectively be entitled to the same rights...', 131),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '129', 'Payment of crossed cheque out of due course.', 'Any banker paying a cheque crossed generally otherwise than to a banker... shall be liable to the true owner of the cheque for any loss he may sustain...', 132),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '130', 'Cheque bearing “not negotiable”.', 'A person taking a cheque crossed generally or specially, bearing in either case the words “not negotiable,” shall not have, and shall not be capable of giving, a better title to the cheque than that which the person from whom he took it had.', 133),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '131', 'Non-liability of banker receiving payment of cheque.', 'A banker who has in good faith and without negligence received payment for a customer of a cheque crossed generally or specially to himself shall not... incur any liability to the true owner...', 134),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XIV', 'OF CROSSED CHEQUES', '131A', 'Application of Chapter to drafts.', 'The provisions of this Chapter shall apply to any draft, as defined in section 85A, as if the draft were a cheque.', 135),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XV', 'OF BILLS IN SETS', '132', 'Set of bills.', 'Bills of exchange may be drawn in parts, each part being numbered and containing a provision that it shall continue payable only so long as the others remain unpaid...', 136),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XV', 'OF BILLS IN SETS', '133', 'Holder of first acquired part entitled to all.', 'As between holders in due course of different parts of the same set, he who first acquired title to his part is entitled to the other parts and the money represented by the bill.', 137),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVI', 'OF INTERNATIONAL LAW', '134', 'Law governing liability of maker, acceptor or indorser of foreign instrument.', 'In the absence of a contract to the contrary, the liability of the maker or drawer of a foreign promissory note... is regulated... by the law of the place where he made the instrument...', 138),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVI', 'OF INTERNATIONAL LAW', '135', 'Law of place of payment governs dishonour.', 'Where a promissory note, bill of exchange or cheque is made payable in a different place... the law of the place where it is made payable determines what constitutes dishonour...', 139),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVI', 'OF INTERNATIONAL LAW', '136', 'Instrument made, etc., out of India, but in accordance with the law of India.', 'If a negotiable instrument is made, drawn, accepted or indorsed outside India, but in accordance with the law of India, the circumstances that any agreement... is invalid according to the law of the country wherein it was entered into does not invalidate any subsequent acceptance or indorsement made thereon within India.', 140),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVI', 'OF INTERNATIONAL LAW', '137', 'Presumption as to foreign law.', 'The law of any foreign country regarding promissory notes, bills of exchange and cheques shall be presumed to be the same as that of India, unless and until the contrary is proved.', 141),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '138', 'Dishonour of cheque for insufficiency, etc., of funds in the account.', 'Where any cheque drawn by a person on an account maintained by him with a banker for payment of any amount of money to another person... is returned by the bank unpaid... such person shall be deemed to have committed an offence and shall... be punished with imprisonment for a term which may extend to two years, or with fine which may extend to twice the amount of the cheque, or with both... (full provisos as per Act).', 142),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '139', 'Presumption in favour of holder.', 'It shall be presumed, unless the contrary is proved, that the holder of a cheque received the cheque... for the discharge, in whole or in part, of any debt or other liability.', 143),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '140', 'Defence which may not be allowed in any prosecution under section 138.', 'It shall not be a defence in a prosecution for an offence under section 138 that the drawer had no reason to believe when he issued the cheque that the cheque may be dishonoured...', 144),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '141', 'Offences by companies.', '(1) If the person committing an offence under section 138 is a company, every person who, at the time the offence was committed, was in charge of, and was responsible to, the company... shall be deemed to be guilty...', 145),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '142', 'Cognizance of offences.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure, 1973— (a) no court shall take cognizance... except upon a complaint... (b) such complaint is made within one month... (2) The offence under section 138 shall be inquired into and tried only by a court within whose local jurisdiction— (a) if the cheque is delivered for collection through an account...', 146),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '142A', 'Validation for transfer of pending cases.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure... all cases transferred to the court having jurisdiction under sub-section (2) of section 142... shall be deemed to have been transferred...', 147),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '143', 'Power of Court to try cases summarily.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure... all offences under this Chapter shall be tried by a Judicial Magistrate of the first class...', 148),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '143A', 'Power to direct interim compensation.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure, the Court trying an offence under section 138 may order the drawer... to pay interim compensation... not exceeding twenty per cent. of the amount of the cheque...', 149),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '144', 'Mode of service of summons.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure... a Magistrate issuing a summons... may direct a copy of summons to be served... by speed post or by such courier services...', 150),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '145', 'Evidence on affidavit.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure, the evidence of the complainant may be given by him on affidavit...', 151),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '146', 'Bank’s slip prima facie evidence of certain facts.', 'The Court shall, in respect of every proceeding under this Chapter, on production of Bank’s slip or memo having thereon the official mark denoting that the cheque has been dishonoured, presume the fact of dishonour...', 152),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '147', 'Offences to be compoundable.', 'Notwithstanding anything contained in the Code of Criminal Procedure, every offence punishable under this Act shall be compoundable.', 153),
('04ac82bd-f734-4fa8-9dbd-d697cfbfcadb', 'CHAPTER XVII', 'OF PENALTIES IN CASE OF DISHONOUR OF CERTAIN CHEQUES FOR INSUFFICIENCY OF FUNDS IN THE ACCOUNTS', '148', 'Power of Appellate Court to order payment pending appeal against conviction.', '(1) Notwithstanding anything contained in the Code of Criminal Procedure, in an appeal by the drawer against conviction under section 138, the Appellate Court may order the appellant to deposit such sum which shall be a minimum of twenty per cent. of the fine or compensation...', 154);